const palette={coral:['#edc0aa','#bb806b','#f6d8c4'],blue:['#b0c7c5','#718e91','#d7dfd3'],ivory:['#f1dfc1','#b49a7e','#faf0dc'],peach:['#e6b69b','#b67d63','#f2d4b5'],ochre:['#e1c5a1','#a98a68','#f6e3c2'],sage:['#d0d1b4','#9b9e80','#eeead5']};
function shellSVG(type,color,id){
  const [base,dark,light]=palette[color];let art='';
  if(type==='fan'){
    const count=13,apex=[100,163];let p='M100 163';const ribs=[];
    for(let j=0;j<=count;j++){const a=Math.PI+j*Math.PI/count,x=100+77*Math.cos(a),y=106+73*Math.sin(a);if(j===0)p+=` Q48 164 ${x} ${y}`;else{const a0=Math.PI+(j-.5)*Math.PI/count,cx=100+85*Math.cos(a0),cy=106+81*Math.sin(a0);p+=` Q${cx} ${cy} ${x} ${y}`;}ribs.push(`<path d="M100 160 Q${100+(x-100)*.35} ${104+(y-104)*.2} ${x} ${y}"/>`);}
    p+=' Q152 164 100 163Z';
    art=`<path d="${p}" fill="url(#g${id})" stroke="${dark}" stroke-width=".9"/><g stroke="${dark}" stroke-width="1.15" fill="none" opacity=".49">${ribs.join('')}</g><g stroke="${light}" stroke-width="2" opacity=".52" fill="none">${ribs.filter((_,i)=>i%2).join('')}</g><path d="M87 160Q100 152 113 160L112 168Q101 175 89 168Z" fill="${base}" stroke="${dark}" stroke-width=".7"/>`;
  }else if(type==='spiral'){
    art=`<path d="M100 24C145 21 176 57 170 101S132 173 87 170 24 132 31 92 57 32 100 24Z" fill="url(#g${id})" stroke="${dark}" stroke-width="1.2"/><path d="M53 139C23 80 83 28 129 53S165 135 116 145 60 111 77 84 122 67 131 92 112 125 98 114 93 94 104 93" stroke="${dark}" stroke-width="2.3" fill="none" opacity=".65"/><path d="M50 134C28 83 80 36 123 56S158 129 117 139 67 111 82 87 121 75 125 94" stroke="${light}" stroke-width="5" fill="none" opacity=".7"/>${Array.from({length:21},(_,i)=>{const a=i*.22+.2;return `<path d="M${100+65*Math.cos(a)} ${99+70*Math.sin(a)}l${8*Math.cos(a+.4)} ${9*Math.sin(a+.4)}" stroke="${dark}" stroke-width="1" opacity=".35"/>`;}).join('')}`;
  }else if(type==='star'){
    let p='';for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,r=i%2?31:85,x=100+r*Math.cos(a),y=105+r*Math.sin(a);p+=`${i?'L':'M'}${x} ${y}`;}p+='Z';
    art=`<path d="${p}" fill="url(#g${id})" stroke="${dark}" stroke-width="1" stroke-linejoin="round"/>${Array.from({length:5},(_,i)=>{const a=-Math.PI/2+i*2*Math.PI/5;return `<path d="M100 105L${100+75*Math.cos(a)} ${105+75*Math.sin(a)}" stroke="${dark}" stroke-width="1.5" stroke-dasharray="1 5" stroke-linecap="round" opacity=".7"/>`}).join('')}<circle cx="100" cy="105" r="7" stroke="${dark}" fill="none" opacity=".4"/>`;
  }else if(type==='conch'){
    art=`<path d="M105 15L118 48Q136 50 137 70 159 82 152 102 162 121 144 138 138 168 101 182L58 164Q51 141 63 122 42 103 64 81 57 57 83 48Z" fill="url(#g${id})" stroke="${dark}" stroke-width="1.2"/><path d="M105 16Q90 56 118 48M83 48Q75 77 137 70M64 81Q90 101 152 102M63 122Q99 137 144 138M58 164Q86 143 107 158L101 182" stroke="${dark}" fill="none" stroke-width="1.5" opacity=".62"/><path d="M118 73Q134 101 109 127T91 173Q116 164 128 143 146 122 135 93Z" fill="${dark}" opacity=".27"/><path d="M107 61Q125 89 110 112T77 151" fill="none" stroke="${light}" stroke-width="5" opacity=".7"/>`;
  }else{
    art=`<path d="M102 27C151 28 176 62 174 108S139 173 96 171 27 141 28 97 59 26 102 27Z" fill="url(#g${id})" stroke="${dark}" stroke-width="1.1"/>${Array.from({length:5},(_,i)=>`<ellipse cx="100" cy="76" rx="8" ry="25" transform="rotate(${i*72} 100 103)" fill="none" stroke="${dark}" stroke-width="1.1" opacity=".6"/>`).join('')}<ellipse cx="101" cy="102" rx="65" ry="64" fill="none" stroke="${dark}" stroke-width="1" stroke-dasharray="1 4" opacity=".4"/><circle cx="100" cy="103" r="4" fill="${dark}" opacity=".28"/>`;
  }
  return `<svg viewBox="0 0 200 200" aria-hidden="true"><defs><radialGradient id="g${id}" cx="35%" cy="25%" r="80%"><stop stop-color="${light}"/><stop offset=".55" stop-color="${base}"/><stop offset="1" stop-color="${dark}"/></radialGradient></defs><g>${art}</g></svg>`;
}
document.querySelectorAll('[data-shell]').forEach((el,i)=>el.innerHTML=shellSVG(el.dataset.shell,el.dataset.color,i));

