const projectDemoURLs = { stars: 'https://eva-gazing-at-stars.streamlit.app/' };
function projectActions(key, p) {
 const localPreview = ['localhost', '127.0.0.1', '::1'].includes(window.location.hostname) || window.location.protocol === 'file:';
 const demoURL = projectDemoURLs[key] || (key === 'stars' && localPreview ? 'http://127.0.0.1:8501' : '');
 const sourceURL = key === 'stars' ? 'https://github.com/Evawangyw/Gazing-at-stars' : p.url;
 const sourceLabel = key === 'stars' ? choose('Explore the source code', '查看项目源码') : p.link;
 const demoLabel = projectDemoURLs[key] ? choose('Try interactive demo', '体验交互演示') : choose('Open local Streamlit demo', '打开本机 Streamlit 演示');
 return `<div class="project-actions">${demoURL ? `<a class="story-demo-link" href="${demoURL}" target="_blank" rel="noopener noreferrer">${demoLabel} ↗</a>` : ''}${sourceURL ? `<a class="story-link" href="${sourceURL}" target="_blank" rel="noopener noreferrer">${sourceLabel} ↗</a>` : ''}</div>`;
}
function renderStory(key){
 let html='';
 if(key==='impact'){html=renderZeroWaste();}
 else if(key==='stars'){html=renderStargazing();}
 else if(data[key]){const p=data[key][lang];html=`<p class="story-eyebrow">${p.eyebrow}</p><h2 id="story-title">${p.title}</h2><p class="story-lead">${p.lead}</p><p class="story-meta">${p.meta}</p><p>${p.body}</p><div class="demo-visual" aria-hidden="true"><div class="visual-heading"><span class="visual-caption">${choose('A QUESTION WORTH FOLLOWING','值得继续追问的问题')}</span>${p.visual}</div><div class="visual-lines">${Array.from({length:18},(_,i)=>`<i style="height:${20+Math.sin(i*1.83)*18+(i%5)*10}px"></i>`).join('')}</div></div><h3>${p.heading}</h3><ul>${p.bullets.map(b=>`<li>${b}</li>`).join('')}</ul><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div>${projectActions(key,p)}`;
 }else if(key==='about'){
 html=choose(`<p class="story-eyebrow">06 / WANDER · A LITTLE ABOUT ME</p><h2 id="story-title">Hi, I’m Eva.<br>Also, Yiwen.</h2><p class="story-lead">A data science and economics student, collecting questions across places and disciplines.</p><div class="city-line"><span>Shanghai</span><i></i><span>Abu Dhabi</span><i></i><span>New York</span></div><p>I’m an undergraduate at NYU Shanghai, studying Data Science & Economics, with study-away experiences at NYU Abu Dhabi and NYU New York.</p><p>My work moves between statistical research, language models, business analytics, and useful products. I enjoy asking what a model tells us, how we can check it, and what someone can actually do with the result.</p><p>Alongside research and internships, I’ve worked as a Writing & Speaking Learning Assistant and an Academic Peer Advisor. Those experiences keep me interested in how we explain ideas and help others navigate unfamiliar things.</p><p>I’m also developing my eye for design. This little shoreline is a place to bring those interests together.</p>`,`<p class="story-eyebrow">06 / 漫游 · 关于我</p><h2 id="story-title">你好，我是逸文。<br>也可以叫我 Eva。</h2><p class="story-lead">学习数据科学与经济学，也在不同城市和学科之间，收集值得追问的问题。</p><div class="city-line"><span>上海</span><i></i><span>阿布扎比</span><i></i><span>纽约</span></div><p>我在上海纽约大学学习数据科学与经济学，曾在纽约大学阿布扎比分校和纽约校区交流学习。</p><p>我的兴趣从统计研究、语言模型和商业分析，延伸到面向真实用户的产品。我喜欢追问：模型告诉了我们什么？怎样验证它？它能帮助一个人做出什么决定？</p><p>除了研究与实习，我也担任过写作与口语学习助理、学术朋辈导师。这些经历让我持续关注如何解释复杂想法，以及如何帮助别人面对陌生的问题。</p><p>我也正在培养自己的设计能力和审美。这片小海滩，是让这些兴趣相遇的地方。</p>`);
 }else if(key==='projects'){html=`<p class="story-eyebrow">${choose('COLLECTED ALONG THE WAY','沿途收集')}</p><h2 id="story-title">${choose('Projects & research','项目与研究')}</h2><p class="story-lead">${choose('A quick guide to what I build and study. Choose a project to explore its story.','快速了解我做过的项目与正在研究的问题，选择一项即可查看完整介绍。')}</p>${projectIndex()}`;
 }else if(key==='notes'){html=renderNotes();
 }else if(Object.hasOwn(noteArticles, key)){html=noteArticles[key]();
 }else if(key==='contact'){
 const email='yw7979@nyu.edu';
 html=choose(`<p class="story-eyebrow">LET’S CONNECT</p><h2 id="story-title">A conversation<br>could start here.</h2><p class="story-lead">I’d love to exchange ideas about data science, NLP, research, and building useful products.</p>`,`<p class="story-eyebrow">打个招呼</p><h2 id="story-title">一段对话，<br>可以从这里开始。</h2><p class="story-lead">欢迎交流数据科学、自然语言处理、研究，或是一起创造有用的产品。</p>`);
 html+=`<div class="project-actions"><a class="story-demo-link" href="mailto:${email}">${email}</a><a class="story-link" href="https://github.com/Evawangyw" target="_blank" rel="noopener noreferrer">${choose('Find me on GitHub','在 GitHub 找到我')} ↗</a></div>`;
 }else if(key==='resume'){html=choose(`<p class="story-eyebrow">EVA WANG / YIWEN</p><h2 id="story-title">Résumé at a glance</h2><p class="story-lead">Data Science & Economics · NYU Shanghai · 2023–2027</p><div class="resume-item"><h3>Research</h3><p>ESG Accountability Analytics · NYU Shanghai<br>Rough Volatility & Financial Time Series · Capstone<br>Sign Language Translation Lab · NYU Abu Dhabi<br>Consumer Decision-Making · Independent Research</p></div><div class="resume-item"><h3>Experience</h3><p>Siemens Healthineers · Business Operations<br>MeetSocial Group · Business Analytics<br>Shanghai SynBio Innovation Center · Industry Research<br>Founder Securities · Industry Research<br>BDO China · Audit</p></div><div class="resume-item"><h3>Selected projects</h3><p>Zero-Waste Knowledge Base · Project Lead<br>Stargazing Assistant</p></div><div class="resume-item"><h3>Tools & methods</h3><p>Python · R · SQL · Tableau · NLP / LLMs · Statistical modeling · Time series</p></div><div class="resume-actions"><button id="print-resume">Print / Save as PDF ↗</button></div><p class="disclosure">A summary for this demo. The final site can link to your application CV.</p>`,`<p class="story-eyebrow">EVA WANG / 王逸文</p><h2 id="story-title">经历概览</h2><p class="story-lead">数据科学与经济学 · 上海纽约大学 · 2023–2027</p><div class="resume-item"><h3>研究</h3><p>ESG 责任文本分析 · 上海纽约大学<br>粗糙波动率与金融时间序列 · 毕业研究<br>手语翻译实验室 · 纽约大学阿布扎比分校<br>消费者决策 · 独立研究</p></div><div class="resume-item"><h3>实习</h3><p>西门子医疗 · 业务运营<br>飞书深诺 · 商业分析<br>上海合成生物学创新中心 · 行业研究<br>方正证券 · 行业研究<br>立信会计师事务所 · 审计</p></div><div class="resume-item"><h3>精选项目</h3><p>零废弃知识库 · 项目组长<br>观星助手</p></div><div class="resume-item"><h3>工具与方法</h3><p>Python · R · SQL · Tableau · NLP / LLM · 统计建模 · 时间序列</p></div><div class="resume-actions"><button id="print-resume">打印 / 另存为 PDF ↗</button></div><p class="disclosure">此处为 demo 的经历摘要，正式版可替换为申请简历。</p>`);
 }
 content.innerHTML=`<article class="story-inner">${fromProjects&&key!=='projects'?`<button class="projects-back" data-open="projects">${choose('← All projects','← 返回项目目录')}</button>`:''}${html}</article>`;
}
function openStory(key){
 const previousStory=currentStory;
 const isNoteArticle=Object.hasOwn(noteArticles, key);
 if(key==='projects'||key==='notes'||isNoteArticle)fromProjects=false;
 else if(previousStory==='projects')fromProjects=true;
 else if(previousStory===null)fromProjects=false;
 if(previousStory!==key)walkthroughIndex=0;
 currentStory=key;
 dialog.classList.toggle('case-dialog',key==='impact'||key==='stars');
 dialog.classList.toggle('stargazing-dialog',key==='stars');
 renderStory(key);
 if(!dialog.open)dialog.showModal();
 dialog.scrollTop=0;
 document.body.style.overflow='hidden';
 if(isNoteArticle)content.querySelector('#story-title').focus({preventScroll:true});
 if(key==='notes'&&Object.hasOwn(noteArticles, previousStory))content.querySelector(`[data-open="${previousStory}"]`)?.focus({preventScroll:true});
}
document.addEventListener('click',e=>{const target=e.target.closest('[data-open]');if(target)openStory(target.dataset.open);if(e.target.closest('#print-resume'))window.print();});
document.getElementById('close-dialog').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close();}});
dialog.addEventListener('close',()=>{document.body.style.overflow='';currentStory=null;fromProjects=false;});
function toggleLanguage(){lang=lang==='en'?'zh':'en';document.documentElement.lang=lang==='en'?'en':'zh-CN';document.querySelectorAll('[data-en]').forEach(el=>el.innerHTML=el.dataset[lang]);document.getElementById('language').textContent=lang==='en'?'中文':'EN';document.getElementById('language').ariaLabel=lang==='en'?'Switch to Chinese':'Switch to English';document.getElementById('close-dialog').innerHTML=`${choose('Close','关闭')} <span>×</span>`;document.getElementById('story-language').textContent=choose('中文','EN');document.getElementById('story-language').ariaLabel=choose('Switch to Chinese','切换到英文');document.getElementById('close-dialog').ariaLabel=choose('Close story','关闭案例');if(currentStory)renderStory(currentStory);}
document.getElementById('language').addEventListener('click',toggleLanguage);
document.getElementById('story-language').addEventListener('click',toggleLanguage);
initWalkthrough();
